// Custom sampler stubs (mapped to noise texture)
#define sampler_pw_noise_lq sampler_noise_lq
#define sat clamp01
sampler sampler_pw_noise_lq;
#define snl sampler_noise_lq
#define pnl sampler_pw_noise_lq
vec3 ball,refl,bcol;
vec2 uv1,uv2,uv3,uv4,dz,dz2,pro,h,v;
float str,ey,a,b,c,s,z,d,k1,p,q, alp,fl,struc,mask,dist,smask,bli;
const float fov=q1,z0=q2,ym=q3,wid=q4,slots=q5,brad=q7;
vec3 scol (float x) {x=x/(slots * 2.0)+0.4;
return .4+0.7*sat (0.5+sin(M_PI / 6.0*(12.0 * x+uTime / 4.0+vec3( 3.0 ,-1,-5))));}
float getr (vec2 uvi) {return 1.0 / (.1+pow(1.0 - GetPixel(uvi).r, 2.0 ));}
float getr1 (vec2 uvi) {return (1.0 - pow(1.0 - GetBlur1(uvi).r, 2.0 ));}
vec3 spa(vec2 uvi,float t)
{vec3 tmp=0; vec2 uv4,uv5=uvi; vec3 m;
for (int n=1; n<6; n++)
{  uv5 = uvi*(1.0 + n*0.5) +vec2(n*0.1,t);
m=texture(pnl,uv5.yx);
tmp+=4.0 * texture(snl,uv5)*(m>0.98)*sin(t*m.z * 128.0);}
return tmp+lum(tmp);}
vec3 noise2(vec2 uvi) {return texture(snl,uvi);}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  //uv = ((uv-0.5)+vec2( 0.0 ,0.02))*0.96+0.5;
uv1 = vec2 (uv.x-0.5, ym-uv.y)*fov;
dist=GetPixel(uv).b;
mask=GetPixel(uv).r>0.02;
struc=GetPixel(uv)*mask;
ey=1.0 - (uv.y-ym)*dist*fov*z0;
if (uv1.y>0) { p=z0*uv1.x;  q=z0*uv1.y+M_PI / 2.0+z0 - 1.0;} //hinten
else if (uv1.y<-1/(z0 - 1.0)) { q=-1/uv1.y * 1.0; p=uv1.x*q;} //vorn
else
{ a=-(1.0 + uv1.y); b=2.0 * uv1.y; c= 1.0 + uv1.y*(z0 - 1.0);
float bet=(b+sqrt(b*b - 4.0*a*c))/(2.0 * a); alp=bet*-(M_PI / 2.0);
q=alp - 1.0+z0; p=uv1.x * (z0+sin(alp) - 1.0);}
uv3 = vec2(p,q);
ret = sat(16.0 * abs(fract(p/wid+0.5)-0.5)) / 4.0;
str = int(p/wid);
smask=(str<slots)*(str>-slots);
ret *= smask;
vec2 ka=texture(pnl,uv3/wid / 256.0);
ret *= (1+1*noise2(uv3*ka.y).x)*scol(str);
pro=noise2(uv3*ka.y).x-noise2(uv3*ka.y+0.001);
bli=pow((1.0 - uv.x+pro.x*(mask == 0.0 ? 1.0 : 0.0)), 7.0 );
ret*=(1.0 + GetBlur1((uv+pro*0.05)).g * 10.0); //shadows
ret *= 0.2+bli ;
k1=1.0 + (1.0 / dist);
h = vec2 (k1, 0.0 )*(vec2(1.0)/uTexSize);
v = vec2 ( 0.0 ,k1)*(vec2(1.0)/uTexSize);
dz.x = getr (uv+h) - getr (uv-h);
dz.y = getr (uv+v) - getr (uv-v);
dz *= mask*0.3;
//streifenbeleuchtung
s=(p/fov/z0+0.5) ;
uv4=fract(vec2(s+dz.x*-.02*(1.0 + ey),wid/fov/z0 / 2.0));
fl = mix(GetBlur1(uv4),GetBlur1(uv4).xy,(mask == 0.0 ? 1.0 : 0.0)).g*1.5;
//#######################################################
uv4=fract(vec2(s, 0.0 )+vec2( 0.0 ,wid/fov/z0 / 2.0));
float bb=GetPixel(uv4).b;
float ll=(4.0 * pow(sin(q10 * 8.0-0.5*uv.x*M_PI), 1114.0 ));
fl += sat(1.0 - pow(q - 7.0, 2.0 )*(3.0 * bb) + 2.0*pro) * bb * (1+0*ll) * (mask == 0.0 ? 1.0 : 0.0);
ret += fl*sat(0.5+q/z0)*scol(str);
ball=dz.y / 3.0;
bcol=scol(+p/wid*sat(1.0 - ey*(1.0 - dist)));
refl=(sat(-dz.y)*(0.5+4*fl))*bcol;
ball+=refl*sat(1.0 - ey*0.);
//lichtreflektion
ball += lum(GetBlur1(fract(uv-dz*0.7)))*mask*bcol;
k1=2.0 + (1.0 - dist) * 6.0;
h = vec2 (k1, 0.0 )*(vec2(1.0)/uTexSize);
v = vec2 ( 0.0 ,k1)*(vec2(1.0)/uTexSize);
dz2.x = getr1 (uv+h) - getr1 (uv-h);
dz2.y = getr1 (uv+v) - getr1 (uv-v);
ball += 0.03/length(dz2-0.2*uv)*struc*(1.0 + bcol);
ball *= 1.0 - dist / 3.0;
k1 = 0.1/length(cos(42.0 * uv*vec2( 1.0 ,0.08)+vec2((uv.y) * 3.0*uv1.x, 0.0 )));
ret = mix(ret,k1* (2.0 + spa(uv,q11*(floor(k1 * 32.0) / 4.0)))*(.5+scol(p/wid)),(smask == 0.0 ? 1.0 : 0.0));
ret = mix(ret,ball,mask);
//ret = GetPixel(uv);
  fragColor = vec4(ret, 1.0);
}

